    """
    index = 0
    length = len(s)

    def parse_value():
        nonlocal index
        if index >= length:
            raise ValueError("Unexpected end of input")

        char = s[index]

        if char == '"':
            return parse_string()
        elif char.isdigit() or char in '-':
            return parse_number()
        elif char == 't':
            return parse_literal("true", True)
        elif char == 'f':
            return parse_literal("false", False)
        elif char == 'n':
            return parse_literal("null", None)
        elif char == '{':
            return parse_object()
        elif char == '[':
            return parse_array()
        else:
            raise ValueError(f"Unexpected character: {char}")

    def parse_string():
        nonlocal index
        index += 1  # Skip opening quote
        result = []
        escape = False

        while index < length:
            char = s[index]
            if escape:
                result.append(char)
                escape = False
            elif char == '\\':
                escape = True
            elif char == '"':
                index += 1  # Skip closing quote
                return ''.join(result)
            else:
                result.append(char)
            index += 1

        raise ValueError("Unterminated string")

    def parse_number():
        nonlocal index
        start = index
        if s[index] == '-':
            index += 1
        while index < length and s[index].isdigit():
            index += 1
        if index < length and s[index] == '.':
            index += 1
            while index < length and s[index].isdigit():
                index += 1
        number = s[start:index]
        return int(number) if '.' not in number else float(number)

    def parse_literal(literal, value):
        nonlocal index
        if s[index:index + len(literal)] == literal:
            index += len(literal)
            return value
        raise ValueError(f"Unexpected literal: expected {literal}")

    def parse_object():
        nonlocal index
        obj = {}
        index += 1  # Skip opening brace
        while index < length:
            skip_whitespace()
            if s[index] == '}':
                index += 1
                return obj
            key = parse_string()
            skip_whitespace()
            if s[index] != ':':
                raise ValueError("Expected ':' after key")
