                return obj
            elif s[index] == ',':
                index += 1  # Skip comma
            else:
                raise ValueError("Expected ',' or '}'")

    def parse_array():
        nonlocal index
        arr = []
        index += 1  # Skip opening bracket
        while index < length:
            skip_whitespace()
            if s[index] == ']':
                index += 1
                return arr
            value = parse_value()
            arr.append(value)
            skip_whitespace()
            if s[index] == ']':
                index += 1
                return arr
            elif s[index] == ',':
                index += 1  # Skip comma
            else:
                raise ValueError("Expected ',' or ']'")

